/bin/zsh -lc "python -c 'import numpy as np, pandas as pd; from analysis import random_effects_shrinkage; df=pd.read_csv(\"data/replication_projects.csv\"); cols=[\"fiso\",\"fisr\",\"se_fiso\",\"se_fisr\"]; print(\"missing\", int(df[cols].isna().sum().sum()), \"nonfinite\", int((~np.isfinite(df[cols].to_numpy())).sum()), \"nonpositive SE\", int((df[[\"se_fiso\",\"se_fisr\"]].to_numpy() <= 0).sum()));
for p in [None,\"Psychology\",\"Experimental Economics\"]:
 r=random_effects_shrinkage(df,p); assert r[\"k\"]==len(df) if p is None else r[\"k\"]==int((df[\"project.x\"]==p).sum()); assert 0<=r[\"I2\"]<=1; assert r[\"ci_low\"]<r[\"mu\"]<r[\"ci_high\"]; print(p, \"checks passed\")'"

